import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../core/api/api_client.dart';
import '../../core/auth/auth_controller.dart';
class LoginScreen extends ConsumerStatefulWidget { const LoginScreen({super.key}); @override ConsumerState<LoginScreen> createState()=>_LoginState(); }
class _LoginState extends ConsumerState<LoginScreen>{final email=TextEditingController(),password=TextEditingController();String? error;bool busy=false;@override void dispose(){email.dispose();password.dispose();super.dispose();}Future<void> _submit(bool register)async{if(email.text.trim().isEmpty||password.text.length<8){setState(()=>error='Введите email и пароль минимум из 8 символов');return;}setState((){busy=true;error=null;});try{final api=ref.read(apiClientProvider);if(register){await api.register(email.text.trim(),password.text);await ref.read(authControllerProvider.notifier).registered();if(mounted)context.go('/onboarding');}else{await api.login(email.text.trim(),password.text);await ref.read(authControllerProvider.notifier).restore();if(mounted)context.go(ref.read(authControllerProvider)==SessionState.authenticated?'/today':'/onboarding');}}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Вход')),body:ListView(padding:const EdgeInsets.all(24),children:[TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Пароль')),if(error!=null)Padding(padding:const EdgeInsets.all(8),child:Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error))),FilledButton(onPressed:busy?null:()=>_submit(false),child:const Text('Войти')),OutlinedButton(onPressed:busy?null:()=>_submit(true),child:const Text('Создать аккаунт и пройти онбординг'))]));}
